files.content:
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a1c2c;
  background-image:
    linear-gradient(45deg, #23263b 25%, transparent 25%),
    linear-gradient(-45deg, #23263b 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #23263b 75%),
    linear-gradient(-45deg, transparent 75%, #23263b 75%);
  background-size: 16px 16px;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0;
  font-family: 'Courier New', Courier, monospace;
  image-rendering: pixelated;
}
.quiz-card {
  background: #f4f4f4;
  padding: 2rem;
  border: 4px solid #000;
  box-shadow: 8px 8px 0 #000;
  text-align: center;
  max-width: 420px;
  width: 90%;
}
h1 {
  margin: 0 0 1rem;
  font-size: 2rem;
  text-shadow: 2px 2px 0 #ffcd75;
}
.answers,
.controls {
  display: flex;
  gap: 1rem;
  justify-content: center;
  margin: 1rem 0;
}
button {
  font: inherit;
  padding: 0.75rem 1.25rem;
  border: 3px solid #000;
  background: #ffcd75;
  box-shadow: 3px 3px 0 #000;
  cursor: pointer;
}
button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  box-shadow: 1px 1px 0 #000;
}
button:focus-visible {
  outline: 3px dashed #fff;
  outline-offset: 2px;
}
.score-row {
  font-size: 1.25rem;
  margin: 0.5rem 0;
}

(function () {
  'use strict';

  var questions = [
    { question: '2 + 2 = ?', answers: ['4', '5'], correctIndex: 0 },
    { question: '3 + 3 = ?', answers: ['5', '6'], correctIndex: 1 }
  ];

  var questionEl = document.getElementById('question');
  var answerA = document.getElementById('answer-a');
  var answerB = document.getElementById('answer-b');
  var scoreEl = document.getElementById('score');
  var nextBtn = document.getElementById('next');
  var restartBtn = document.getElementById('restart');

  var currentIndex = 0;
  var answered = false;
  var score = 0;

  function setScore(value) {
    score = Math.floor(Number(value)) || 0;
    scoreEl.textContent = score;
  }

  function renderCurrentQuestion() {
    var q = questions[currentIndex];
    questionEl.textContent = q.question;
    answerA.textContent = q.answers[0];
    answerB.textContent = q.answers[1];
    answerA.disabled = false;
    answerB.disabled = false;
    answered = false;
  }

  function lockAnswers() {
    answerA.disabled = true;
    answerB.disabled = true;
    answered = true;
  }

  function handleAnswer(index) {
    if (answered) return;
    lockAnswers();
    if (questions[currentIndex].correctIndex === index) {
      setScore(score + 1);
    }
  }

  answerA.addEventListener('click', function () {
    handleAnswer(0);
  });

  answerB.addEventListener('click', function () {
    handleAnswer(1);
  });

  nextBtn.addEventListener('click', function () {
    if (currentIndex < questions.length - 1) {
      currentIndex += 1;
      renderCurrentQuestion();
    } else {
      questionEl.textContent = 'Finished';
      answerA.disabled = true;
      answerB.disabled = true;
      answered = true;
    }
  });

  restartBtn.addEventListener('click', function () {
    currentIndex = 0;
    setScore(0);
    renderCurrentQuestion();
  });

  renderCurrentQuestion();
})();
